import {
  FluentProvider,
  webLightTheme,
  Button,
  MessageBar,
  MessageBarBody,
  Title1,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useEffect, useRef } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useCurrentUser } from '../hooks/useCurrentUser'
import { type AcceptInviteError, useAcceptInvite } from '../hooks/useAcceptInvite'

const useStyles = makeStyles({
  root: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh',
    gap: tokens.spacingVerticalL,
    textAlign: 'center',
    padding: tokens.spacingHorizontalXXL,
  },
})

export default function AcceptInvitePage() {
  const styles = useStyles()
  const { token } = useParams<{ token: string }>()
  const navigate = useNavigate()
  const { isUnauthenticated } = useCurrentUser()
  const { mutateAsync, error } = useAcceptInvite()
  const hasAttempted = useRef(false)

  useEffect(() => {
    if (hasAttempted.current) return
    if (!isUnauthenticated && token) {
      hasAttempted.current = true
      mutateAsync(token).then(() => navigate('/')).catch(() => {})
    }
  }, [isUnauthenticated, token, mutateAsync, navigate])

  const acceptError = error as AcceptInviteError | null

  return (
    <FluentProvider theme={webLightTheme}>
      <div className={styles.root}>
        <Title1 as="h1">Accept Invitation</Title1>

        {isUnauthenticated && (
          <Button
            as="a"
            appearance="primary"
            href={`/api/v1/auth/signin?returnUrl=${encodeURIComponent(`/accept/${token ?? ''}`)}`}
            aria-label="Accept and Sign in with Google"
          >
            Accept &amp; Sign in with Google
          </Button>
        )}

        {acceptError?.status === 410 && (
          <MessageBar intent="error">
            <MessageBarBody>
              This invitation is no longer valid. Please request a new one.
            </MessageBarBody>
          </MessageBar>
        )}

        {acceptError?.status === 422 && (
          <MessageBar intent="error">
            <MessageBarBody>
              This invitation was issued to a different email address.
            </MessageBarBody>
          </MessageBar>
        )}
      </div>
    </FluentProvider>
  )
}

import { useQuery } from '@tanstack/react-query'

export interface CurrentUser {
  id: string
  email: string
  displayName: string
  systemRole: 'admin' | 'standard'
  registeredAt: string
  lastSignInAt: string | null
}

class HttpError extends Error {
  constructor(public readonly status: number) {
    super(`HTTP ${status}`)
    this.name = 'HttpError'
  }
}

async function fetchCurrentUser(): Promise<CurrentUser> {
  const response = await fetch('/api/v1/auth/me')
  if (!response.ok) throw new HttpError(response.status)
  return response.json() as Promise<CurrentUser>
}

export interface UseCurrentUserResult {
  user: CurrentUser | undefined
  isLoading: boolean
  isUnauthenticated: boolean
  isNotRegistered: boolean
  isError: boolean
}

export function useCurrentUser(): UseCurrentUserResult {
  const { data, isLoading, isError, error } = useQuery({
    queryKey: ['currentUser'],
    queryFn: fetchCurrentUser,
    retry: false,
  })

  const isUnauthenticated = isError && error instanceof HttpError && error.status === 401
  const isNotRegistered = isError && error instanceof HttpError && error.status === 403

  return {
    user: data,
    isLoading,
    isUnauthenticated,
    isNotRegistered,
    isError,
  }
}

