using System.Data;
using System.Security.Claims;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain;
using Kanban.Domain.Entities;
using Kanban.Domain.Enums;
using Kanban.Domain.Events;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.Retry;

namespace Kanban.Business.Services;

public sealed class AuthService : IAuthService
{
    private readonly IUserRepository _userRepository;
    private readonly IAuthEventRepository _authEventRepository;
    private readonly IDbConnection _dbConnection;
    private readonly IDbConnectionFactory _transactionFactory;
    private readonly ILogger<AuthService> _logger;

    private static readonly ResiliencePipeline RetryPolicy =
        new ResiliencePipelineBuilder()
            .AddRetry(new RetryStrategyOptions
            {
                MaxRetryAttempts = 5,
                Delay = TimeSpan.FromMilliseconds(50),
                BackoffType = DelayBackoffType.Exponential,
                UseJitter = true,
                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
            })
            .Build();

    public AuthService(
        IUserRepository userRepository,
        IAuthEventRepository authEventRepository,
        IDbConnection dbConnection,
        IDbConnectionFactory transactionFactory,
        ILogger<AuthService> logger)
    {
        Verify.That(userRepository).IsNotNull();
        Verify.That(authEventRepository).IsNotNull();
        Verify.That(dbConnection).IsNotNull();
        Verify.That(transactionFactory).IsNotNull();
        Verify.That(logger).IsNotNull();
        _userRepository = userRepository;
        _authEventRepository = authEventRepository;
        _dbConnection = dbConnection;
        _transactionFactory = transactionFactory;
        _logger = logger;
    }

    public async Task<CurrentUserDto?> GetCurrentUserAsync(
        Guid userId,
        CancellationToken cancellationToken = default)
    {
        Verify.That(userId).IsNotDefault();
        var user = await _userRepository.FindByIdAsync(userId);
        return user is null ? null : UserTransforms.ToDto(user);
    }

    public async Task HandleSignInAsync(
        string googleSub,
        string email,
        ClaimsIdentity claimsIdentity,
        CancellationToken cancellationToken = default)
    {
        Verify.That(googleSub).IsNotNull().IsNotEmpty();
        Verify.That(email).IsNotNull().IsNotEmpty();
        Verify.That(claimsIdentity).IsNotNull();

        await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var user = await _userRepository.FindByGoogleSubAsync(googleSub, tx);

                if (user is null)
                {
                    var userByEmail = await _userRepository.FindByEmailAsync(email, tx);
                    if (userByEmail is not null && userByEmail.GoogleSub is null)
                    {
                        await _userRepository.LinkGoogleSubAsync(userByEmail.Id, googleSub, tx);
                        userByEmail.LinkGoogleIdentity(googleSub);
                        user = userByEmail;
                    }
                }

                if (user is not null)
                {
                    claimsIdentity.AddClaim(new Claim("user_id", user.Id.ToString()));
                    claimsIdentity.AddClaim(new Claim("system_role",
                        user.SystemRole == SystemRole.Admin ? "admin" : "standard"));

                    var signedInAt = DateTimeOffset.UtcNow;
                    await _userRepository.UpdateLastSignInAsync(user.Id, signedInAt, tx);

                    var authEvent = new AuthEvent(
                        Id: Guid.NewGuid(),
                        OccurredAt: signedInAt,
                        EventType: AuthEventType.SignIn,
                        UserId: user.Id,
                        Outcome: "success");
                    await _authEventRepository.RecordAsync(authEvent, tx);

                    _logger.LogInformation(
                        "User {UserId} signed in with role {SystemRole}", user.Id, user.SystemRole);
                }
                else
                {
                    var authEvent = new AuthEvent(
                        Id: Guid.NewGuid(),
                        OccurredAt: DateTimeOffset.UtcNow,
                        EventType: AuthEventType.SignIn,
                        UserId: null,
                        Outcome: "unregistered");
                    await _authEventRepository.RecordAsync(authEvent, tx);

                    _logger.LogWarning("Unregistered Google user attempted sign-in");
                }

                tx.Commit();
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, cancellationToken);
    }
}

using System.Data;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain;
using Kanban.Domain.Entities;
using Kanban.Domain.Enums;
using Kanban.Domain.Events;
using Kanban.Domain.Exceptions;
using Kanban.Domain.ValueObjects;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.Retry;

namespace Kanban.Business.Services;

public sealed class InvitationService : IInvitationService
{
    private readonly IUserRepository _userRepository;
    private readonly IInvitationRepository _invitationRepository;
    private readonly IAuthEventRepository _authEventRepository;
    private readonly IDbConnection _dbConnection;
    private readonly IDbConnectionFactory _transactionFactory;
    private readonly ILogger<InvitationService> _logger;

    private static readonly ResiliencePipeline RetryPolicy =
        new ResiliencePipelineBuilder()
            .AddRetry(new RetryStrategyOptions
            {
                MaxRetryAttempts = 5,
                Delay = TimeSpan.FromMilliseconds(50),
                BackoffType = DelayBackoffType.Exponential,
                UseJitter = true,
                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
            })
            .Build();

    public InvitationService(
        IUserRepository userRepository,
        IInvitationRepository invitationRepository,
        IAuthEventRepository authEventRepository,
        IDbConnection dbConnection,
        IDbConnectionFactory transactionFactory,
        ILogger<InvitationService> logger)
    {
        Verify.That(userRepository).IsNotNull();
        Verify.That(invitationRepository).IsNotNull();
        Verify.That(authEventRepository).IsNotNull();
        Verify.That(dbConnection).IsNotNull();
        Verify.That(transactionFactory).IsNotNull();
        Verify.That(logger).IsNotNull();
        _userRepository = userRepository;
        _invitationRepository = invitationRepository;
        _authEventRepository = authEventRepository;
        _dbConnection = dbConnection;
        _transactionFactory = transactionFactory;
        _logger = logger;
    }

    public async Task<(IssueInviteResponse Response, bool IsNew)> IssueAsync(
        string email,
        Guid issuedByUserId,
        SystemRole callerRole,
        string frontendBaseUrl,
        CancellationToken cancellationToken = default)
    {
        Verify.That(email).IsNotNull().IsNotEmpty();
        Verify.That(issuedByUserId).IsNotDefault();
        Verify.That(frontendBaseUrl).IsNotNull().IsNotEmpty();

        if (callerRole != SystemRole.Admin)
            throw new ForbiddenException("invite.forbidden", "Only admins can issue invitations.");

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var existing = await _invitationRepository.FindActiveByEmailAsync(email, tx);
                if (existing is not null)
                {
                    var refreshToken = InvitationToken.Generate();
                    var newExpiry = DateTimeOffset.UtcNow.AddDays(7);
                    await _invitationRepository.RefreshTokenAsync(
                        existing.Id, refreshToken.Hash, newExpiry, tx);
                    tx.Commit();
                    _logger.LogInformation(
                        "Active invitation refreshed by {IssuedByUserId}", issuedByUserId);
                    return (InvitationTransforms.ToResponse(refreshToken.Raw, newExpiry, frontendBaseUrl), false);
                }

                var registeredUser = await _userRepository.FindByEmailAsync(email, tx);
                if (registeredUser is not null)
                    throw new ConflictException(
                        "invite.already_registered", "This email address is already registered.");

                var token = InvitationToken.Generate();
                var issuedAt = DateTimeOffset.UtcNow;
                var invitation = new Invitation(
                    id: Guid.NewGuid(),
                    email: email,
                    issuedByUserId: issuedByUserId,
                    tokenHash: token.Hash,
                    issuedAt: issuedAt,
                    expiresAt: issuedAt.AddDays(7),
                    consumedAt: null,
                    consumedByUserId: null);

                await _invitationRepository.InsertAsync(invitation, tx);

                var authEvent = new AuthEvent(
                    Id: Guid.NewGuid(),
                    OccurredAt: issuedAt,
                    EventType: AuthEventType.InvitationIssued,
                    UserId: issuedByUserId,
                    Outcome: "success");
                await _authEventRepository.RecordAsync(authEvent, tx);

                tx.Commit();

                _logger.LogInformation(
                    "Invitation issued by {IssuedByUserId}", issuedByUserId);

                return (InvitationTransforms.ToResponse(invitation, token.Raw, frontendBaseUrl), true);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, cancellationToken);
    }

    public async Task<User> AcceptAsync(
        string rawToken,
        string googleEmail,
        string googleSub,
        string displayName,
        CancellationToken cancellationToken = default)
    {
        Verify.That(rawToken).IsNotNull().IsNotEmpty();
        Verify.That(googleEmail).IsNotNull().IsNotEmpty();
        Verify.That(googleSub).IsNotNull().IsNotEmpty();
        Verify.That(displayName).IsNotNull().IsNotEmpty();

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            var tokenHash = InvitationToken.HashRaw(rawToken);
            var acceptedAt = DateTimeOffset.UtcNow;
            var newUserId = Guid.NewGuid();

            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                // Atomic gate: marks consumed_at — serialises concurrent accepts.
                // consumed_by_user_id is set separately below (after user is created) to avoid
                // FK constraint violations in Microsoft.Data.Sqlite 10+ which enforces them by
                // default, unlike previous versions.
                var consumed = await _invitationRepository.TryConsumeAsync(tokenHash, acceptedAt, tx);
                if (!consumed)
                    throw new NotFoundException(
                        "invite.invalid",
                        "This invitation is no longer valid. Please request a new one.");

                var invitation = await _invitationRepository.FindByTokenHashAsync(tokenHash, tx);
                if (invitation is null || !invitation.EmailMatches(googleEmail))
                    throw new BusinessRuleException(
                        "invite.email_mismatch",
                        "This invitation was issued to a different email address.");

                var user = new User(
                    id: newUserId,
                    email: invitation.Email,
                    displayName: displayName,
                    systemRole: SystemRole.Standard,
                    googleSub: googleSub,
                    registeredAt: acceptedAt,
                    lastSignInAt: null);

                await _userRepository.InsertAsync(user, tx);

                // FK constraint satisfied now that the user row exists
                await _invitationRepository.RecordConsumerAsync(tokenHash, newUserId, tx);

                var authEvent = new AuthEvent(
                    Id: Guid.NewGuid(),
                    OccurredAt: acceptedAt,
                    EventType: AuthEventType.InvitationAccepted,
                    UserId: newUserId,
                    Outcome: "success");
                await _authEventRepository.RecordAsync(authEvent, tx);

                tx.Commit();

                _logger.LogInformation("Invitation accepted by user {UserId}", newUserId);
                return user;
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, cancellationToken);
    }
}

import { test as setup, expect } from '@playwright/test'
import fs from 'fs'
import {
  ADMIN_AUTH, INVITEE_AUTH, UNREGISTERED_AUTH,
  API_BASE, WEB_BASE,
  ADMIN_EMAIL, INVITEE_EMAIL, UNREGISTERED_EMAIL,
} from './auth.helpers'

const BYPASS = process.env.PLAYWRIGHT_AUTH_BYPASS === 'true'

setup.beforeAll(() => {
  fs.mkdirSync('playwright/.auth', { recursive: true })
  const emptyState = JSON.stringify({ cookies: [], origins: [] })
  for (const p of [INVITEE_AUTH, UNREGISTERED_AUTH]) {
    if (!fs.existsSync(p)) fs.writeFileSync(p, emptyState)
  }
})

// ── CI / bypass path ──────────────────────────────────────────────────────────
// Calls GET /api/v1/dev/authenticate which issues the cookie without Google OAuth
// and redirects to the frontend. Only registered when ASPNETCORE_ENVIRONMENT=Development.

setup('bypass: authenticate as admin', async ({ page }) => {
  setup.skip(!BYPASS, 'bypass path only — run with PLAYWRIGHT_AUTH_BYPASS=true')
  await page.goto(`${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(ADMIN_EMAIL)}`)
  await page.waitForURL(`${WEB_BASE}/**`)
  await page.context().storageState({ path: ADMIN_AUTH })
})

setup('authenticate as unregistered invitee', async ({ page }) => {
  // No Google sign-in path exists for test invitees — dev endpoint is the only option
  // regardless of whether PLAYWRIGHT_AUTH_BYPASS is set.
  await page.goto(
    `${API_BASE}/api/v1/dev/authenticate` +
    `?email=${encodeURIComponent(INVITEE_EMAIL)}&displayName=Playwright+Invitee`,
  )
  await page.waitForURL(`${WEB_BASE}/**`)
  await page.context().storageState({ path: INVITEE_AUTH })
})

setup('authenticate as unregistered non-invited user', async ({ page }) => {
  // No Google sign-in path exists for test non-invited users — dev endpoint is the only option.
  await page.goto(
    `${API_BASE}/api/v1/dev/authenticate` +
    `?email=${encodeURIComponent(UNREGISTERED_EMAIL)}&displayName=Playwright+Unregistered`,
  )
  await page.waitForURL(`${WEB_BASE}/**`)
  await page.context().storageState({ path: UNREGISTERED_AUTH })
})

// ── Demo / real Google path ───────────────────────────────────────────────────
// Opens a headed browser window and waits (up to 2 minutes) for you to complete
// Google sign-in manually. Run once with: npm run test:e2e:setup
// The saved state is reused for all subsequent demo runs.

setup('google: authenticate as admin', async ({ page, context }) => {
  setup.skip(BYPASS, 'real Google path only — run without PLAYWRIGHT_AUTH_BYPASS=true')
  setup.skip(fs.existsSync(ADMIN_AUTH), 'saved session exists — delete playwright/.auth/admin.json to force re-auth')
  setup.setTimeout(180_000)
  await page.goto(`${WEB_BASE}/signin`)
  await expect(page.getByRole('link', { name: /sign in with google/i })).toBeVisible()
  await page.click('a[href*="/api/v1/auth/signin"]')
  // Wait up to 3 minutes for the user to complete Google sign-in in the browser window
  await page.waitForURL(`${WEB_BASE}/**`, { timeout: 170_000 })
  await expect(page).not.toHaveURL(/\/signin/)
  await context.storageState({ path: ADMIN_AUTH })
})

