import { test, expect } from '@playwright/test'
import {
  ADMIN_AUTH, INVITEE_AUTH,
  API_BASE, WEB_BASE,
  INVITEE_EMAIL,
} from '../auth.helpers'

// ── US2: Admin issues an invitation ──────────────────────────────────────────
// These scenarios require the board page (InviteUserDialog lives there).
// Scaffolded now; will be completed in the board feature spec.

test.describe('US2: Admin issues an invitation', () => {
  test.use({ storageState: ADMIN_AUTH })

  test('scenario 1 — admin submits valid email and receives redemption link', async ({ page }) => {
    test.fixme(true, 'Requires board page — InviteUserDialog not yet accessible')
    await page.goto('/')
    await expect(page.getByRole('main', { name: /kanban board/i })).toBeVisible()
  })

  test('scenario 2 — re-invite of unconsumed email returns existing link without duplicate', async ({ page }) => {
    test.fixme(true, 'Requires board page')
    await page.goto('/')
  })

  test('scenario 3 — re-invite of expired email issues fresh invitation', async ({ page }) => {
    test.fixme(true, 'Requires board page')
    await page.goto('/')
  })

  test('scenario 4 — non-admin user is refused with permission denied', async ({ page }) => {
    test.fixme(true, 'Requires board page')
    await page.goto('/')
  })

  test('scenario 5 — invalid email format is rejected with validation error', async ({ page }) => {
    test.fixme(true, 'Requires board page')
    await page.goto('/')
  })
})

// ── US3: Invitee accepts an invitation ───────────────────────────────────────

test.describe('US3: Invitee accepts an invitation', () => {
  test('scenario 1 — valid token with matching email creates registered user', async ({
    browser,
    request,
  }) => {
    const uniqueEmail = `invitee-${Date.now()}@example.com`

    const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed/invitation`, {
      data: { email: uniqueEmail },
    })
    expect(seedResp.ok()).toBeTruthy()
    const { token } = await seedResp.json()

    const ctx = await browser.newContext()
    const page = await ctx.newPage()
    await page.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(uniqueEmail)}&displayName=Scenario+1+Invitee`,
    )
    await page.waitForURL(`${WEB_BASE}/**`)

    await page.goto(`${WEB_BASE}/accept/${token}`)
    await expect(page).toHaveURL(`${WEB_BASE}/`, { timeout: 15_000 })
    await expect(page.getByRole('main', { name: /kanban board/i })).toBeVisible()

    await ctx.close()
  })

  test('scenario 2 — invitee can sign in via regular flow after accepting', async ({ page }) => {
    test.fixme(true, 'Depends on scenario 1 having registered the invitee; requires board page for full verification')
    await page.goto('/')
  })

  test.describe('error states — use invitee auth cookie', () => {
    test.use({ storageState: INVITEE_AUTH })

    test('scenario 3 — expired token shows invitation-no-longer-valid error', async ({
      page,
      request,
    }) => {
      const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed/invitation`, {
        data: { email: INVITEE_EMAIL, expiresInDays: -1 },
      })
      const { token } = await seedResp.json()

      await page.goto(`${WEB_BASE}/accept/${token}`)
      await expect(
        page.getByRole('alert').filter({ hasText: /no longer valid|invite\.invalid/i }),
      ).toBeVisible({ timeout: 10_000 })
    })

    test('scenario 4 — consumed token shows same invalid message as expired', async ({
      page,
      request,
    }) => {
      const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed/invitation`, {
        data: { email: INVITEE_EMAIL, consumed: true },
      })
      const { token } = await seedResp.json()

      await page.goto(`${WEB_BASE}/accept/${token}`)
      await expect(
        page.getByRole('alert').filter({ hasText: /no longer valid|invite\.invalid/i }),
      ).toBeVisible({ timeout: 10_000 })
    })

    test('scenario 5 — email mismatch shows different email address message', async ({
      page,
      request,
    }) => {
      // Invitation is for a different email; cookie is for INVITEE_EMAIL
      const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed/invitation`, {
        data: { email: 'different-addressee@example.com' },
      })
      const { token } = await seedResp.json()

      await page.goto(`${WEB_BASE}/accept/${token}`)
      await expect(
        page.getByRole('alert').filter({ hasText: /different email|invite\.email_mismatch/i }),
      ).toBeVisible({ timeout: 10_000 })
    })

    test('scenario 6 — fabricated token shows same invalid message', async ({ page }) => {
      const fakeToken = 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA'
      await page.goto(`${WEB_BASE}/accept/${fakeToken}`)
      await expect(
        page.getByRole('alert').filter({ hasText: /no longer valid|invite\.invalid/i }),
      ).toBeVisible({ timeout: 10_000 })
    })
  })
})

import {
  FluentProvider,
  webLightTheme,
  Button,
  MessageBar,
  MessageBarBody,
  Title1,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useEffect, useRef } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useCurrentUser } from '../hooks/useCurrentUser'
import { type AcceptInviteError, useAcceptInvite } from '../hooks/useAcceptInvite'

const useStyles = makeStyles({
  root: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh',
    gap: tokens.spacingVerticalL,
    textAlign: 'center',
    padding: tokens.spacingHorizontalXXL,
  },
})

export default function AcceptInvitePage() {
  const styles = useStyles()
  const { token } = useParams<{ token: string }>()
  const navigate = useNavigate()
  const { isUnauthenticated } = useCurrentUser()
  const { mutateAsync, error } = useAcceptInvite()
  const hasAttempted = useRef(false)

  useEffect(() => {
    if (hasAttempted.current) return
    if (!isUnauthenticated && token) {
      hasAttempted.current = true
      mutateAsync(token).then(() => navigate('/')).catch(() => {})
    }
  }, [isUnauthenticated, token, mutateAsync, navigate])

  const acceptError = error as AcceptInviteError | null

  return (
    <FluentProvider theme={webLightTheme}>
      <div className={styles.root}>
        <Title1 as="h1">Accept Invitation</Title1>

        {isUnauthenticated && (
          <Button
            as="a"
            appearance="primary"
            href={`/api/v1/auth/signin?returnUrl=${encodeURIComponent(`/accept/${token ?? ''}`)}`}
            aria-label="Accept and Sign in with Google"
          >
            Accept &amp; Sign in with Google
          </Button>
        )}

        {acceptError?.status === 410 && (
          <MessageBar intent="error" role="alert">
            <MessageBarBody>
              This invitation is no longer valid. Please request a new one.
            </MessageBarBody>
          </MessageBar>
        )}

        {acceptError?.status === 422 && (
          <MessageBar intent="error" role="alert">
            <MessageBarBody>
              This invitation was issued to a different email address.
            </MessageBarBody>
          </MessageBar>
        )}
      </div>
    </FluentProvider>
  )
}

using System.Data;
using System.Security.Claims;
using Dapper;
using Kanban.Api.Options;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain.Enums;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.Extensions.Options;

namespace Kanban.Api.Endpoints;

// Dev-only test infrastructure — architecture boundary exception.
// Direct DataAccess and Domain usage is intentional here; this file is
// never registered outside IsDevelopment() and must not ship to production.
internal static class DevEndpoints
{
    internal static void Map(IEndpointRouteBuilder routes)
    {
        routes.MapGet("/dev/authenticate",
            async (
                string email,
                string? displayName,
                IUserRepository userRepository,
                IOptions<CorsOptions> corsOptions,
                HttpContext ctx) =>
            {
                var user = await userRepository.FindByEmailAsync(email);

                List<Claim> claims;
                if (user is not null)
                {
                    claims =
                    [
                        new Claim("sub", user.GoogleSub ?? $"dev-sub-{email}"),
                        new Claim("email", user.Email),
                        new Claim("name", user.DisplayName),
                        new Claim("user_id", user.Id.ToString()),
                        new Claim("system_role",
                            user.SystemRole == SystemRole.Admin ? "admin" : "standard"),
                    ];
                }
                else
                {
                    claims =
                    [
                        new Claim("sub", $"dev-sub-{email}"),
                        new Claim("email", email),
                        new Claim("name", displayName ?? email),
                    ];
                }

                var identity = new ClaimsIdentity(
                    claims, CookieAuthenticationDefaults.AuthenticationScheme);
                await ctx.SignInAsync(
                    CookieAuthenticationDefaults.AuthenticationScheme,
                    new ClaimsPrincipal(identity));

                var frontendOrigin = corsOptions.Value.AllowedOrigins.FirstOrDefault()
                    ?? "http://localhost:5173";
                return Results.Redirect(frontendOrigin);
            })
            .WithName("DevAuthenticate")
            .WithSummary("[DEV ONLY] Issue an auth cookie without Google OAuth — Playwright use only")
            .AllowAnonymous();

        routes.MapPost("/dev/seed/invitation",
            async (
                DevSeedInvitationRequest request,
                IDbConnection db) =>
            {
                var adminId = await db.QuerySingleOrDefaultAsync<string>(
                    "SELECT id FROM users WHERE system_role = 'Admin' LIMIT 1");

                if (adminId is null)
                    return Results.NotFound("No admin user found in database");

                var (rawToken, tokenHash) = GenerateToken();
                var now = DateTimeOffset.UtcNow;
                var expiresAt = now.AddDays(request.ExpiresInDays ?? 7);
                var consumedAt = request.Consumed ? now.AddMinutes(-1) : (DateTimeOffset?)null;

                await db.ExecuteAsync(
                    """
                    INSERT INTO invitations
                        (id, email, issued_by_user_id, token_hash, issued_at, expires_at, consumed_at, consumed_by_user_id)
                    VALUES (@id, @email, @issuedByUserId, @tokenHash, @issuedAt, @expiresAt, @consumedAt, NULL)
                    """,
                    new
                    {
                        id = Guid.NewGuid().ToString("D"),
                        email = request.Email,
                        issuedByUserId = adminId,
                        tokenHash,
                        issuedAt = now.ToString("o"),
                        expiresAt = expiresAt.ToString("o"),
                        consumedAt = consumedAt?.ToString("o"),
                    });

                return Results.Ok(new { token = rawToken });
            })
            .WithName("DevSeedInvitation")
            .WithSummary("[DEV ONLY] Seed an invitation record for Playwright testing")
            .AllowAnonymous();
    }

    private static (string rawToken, string tokenHash) GenerateToken()
    {
        var bytes = System.Security.Cryptography.RandomNumberGenerator.GetBytes(32);
        var raw = Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        var hash = Convert.ToHexString(
            System.Security.Cryptography.SHA256.HashData(
                System.Text.Encoding.UTF8.GetBytes(raw))).ToLower();
        return (raw, hash);
    }
}

internal sealed record DevSeedInvitationRequest(
    string Email,
    double? ExpiresInDays = null,
    bool Consumed = false);

