96	                {
97	                    claimsIdentity.AddClaim(new Claim("user_id", user.Id.ToString()));
98	                    claimsIdentity.AddClaim(new Claim("system_role",
99	                        user.SystemRole == SystemRole.Admin ? "admin" : "standard"));
100	
